{-# LANGUAGE OverloadedStrings #-}
-- | The class (a) record-helper comparison table.
--
-- One row per owned body with a stock-shaped export whose stock extent is in
-- image 4 or 5, whose stock body makes no call outside the compared set, and
-- which touches no coprocessor or device address. Each row is derived from the
-- stock disassembly and the x70view 55436fc C definition: the staged pages are
-- the 64 KiB-aligned spans holding every constant data address the body and its
-- compared callees reach outside the mapped code, the pointer slots are the
-- words those bodies load and then use as an address base (including incoming
-- stack arguments), and the argument lists name the entry registers the stock
-- signature and the body use as a pointer or a scalar. A case is (fill pattern,
-- scalar argument values in parameter order); pointer arguments receive a
-- staged buffer.
module Replacement.PowerLifecycle.RecordHelperTable (Helper (..), Image (..), allHelpers, helperStagedWords, helperTableIdentity) where

import Data.Word (Word32)
import Emulation.NativeObservation (Register (..))

data Image = Image4 | Image5 deriving (Eq, Show)

data Helper = Helper
  { helperAddress :: String
  , helperModule :: String
  , helperEntry :: Word32
  , helperSize :: Word32
  , helperImage :: Image
  , helperReturnRegisters :: [Register]
  , helperPointerArguments :: [Register]
  , helperScalarArguments :: [Register]
  , helperDataPages :: [(Word32, Word32)]
  , helperPointerSlots :: [(Word32, Word32)]
  , helperStockExtents :: [(Word32, Word32)]
  , helperMinimumInstructions :: Int
  , helperCases :: [(Int, [Word32])]
  }

helperTableIdentity :: String
helperTableIdentity = "x70view 55436fc85c0560dd252b0410af6f2427fe198cd3; image4 base 0x0061c400; image5 base 0x00bf1a00; class (a) rows derived from the stock extent disassembly and the decomp C definition"

-- | Staged words the per-row derivation cannot express: a loop bound the stock
-- body loads from an argument buffer. The value keeps the loop inside the
-- staged 64 KiB buffer.
helperStagedWords :: Helper -> [(Word32, Word32)]
helperStagedWords helper = case helperAddress helper of
  "eebc30" -> [(0x00340000, 1)]
  "eebca4" -> [(0x00340000, 1)]
  _ -> []

